class LightBulb with Listener<bool> {
  LightBulb() {
    listen();
  }

  bool enabled = false;

  @override
  void onMessage(bool message) {
    enabled = message;
  }

  void dispose() {
    cancel();
  }
}

class LightSwitch with Sender<bool> {
  void enable() {
    send(true);
  }
}
